actions.script:
// TODO: verify this assumption: this assumes every child item has exactly 1 parent

// Set up the final, merged list:
invoiceItemList = []

// This is for efficiency:
def lastIndexMarkedAsAdded = 0

def numberOfParents = parentAndSoloInvoicesList.size()
def numberOfChildren = childInvoicesList.size()

// Go through every parent:
for (def j = 0; numberOfParents > j; j++) {

    // Add the parent or solo item:
    invoiceItemList.add(parentAndSoloInvoicesList[j])

    // Add the parent's override to the map. This will always be null at first:
    invoiceItemGLAccountIdMap[parentAndSoloInvoicesList[j].invoiceItemSeqId] = parentAndSoloInvoicesList[j].overrideGlAccountId

    // Go through the remaining children that we haven't added yet:
    for (def i = lastIndexMarkedAsAdded; numberOfChildren > i; i++) {

        // If this child belongs with this parent:
        if (parentAndSoloInvoicesList[j].invoiceItemSeqId == childInvoicesList[i].parentItemSeqId) {

            // Add the child to the list here:
            invoiceItemList.add(childInvoicesList[i])

            // Start the index later in the list so we don't waste time reviewing children we already added:
            lastIndexMarkedAsAdded++
        } else {
            // This child does not belong with this parent.
            // Stop this inner loop:
            break
        }
    }
}

// If not all children were added:
if (numberOfChildren > lastIndexMarkedAsAdded) {

    // This will send a growl to the user:
    throw new Exception("Error some child item invoices have no parent items.")
}

